import math

def is_strictly_convex(points):
    def cross_product(p1, p2, p3):
        return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])

    def orientation(p, q, r):
        val = cross_product(q, r, p)
        if val > 0:
            return +1  # clockwise
        elif val < 0:
            return -1  # counterclockwise
        else:
            return 0  # collinear

    orientation_sum = 0

    for i in range(3):
        j = (i + 1) % 3
        k = (i + 2) % 3

        orientation_sum += orientation(points[0], points[i], points[k])

    if orientation_sum == 0:
        return False
    else:
        return True

