def count_mirrors(n, gaps):
    factors = [0] * (n + 1)
    for i in range(2, n + 1):
        if factors[i] == 0:
            factors[i] = i
            for j in range(i, n + 1, i):
                factors[j] = i
    mask = (1 << n) - 1
    ways = 0
    for gap in gaps:
        if gap != 0:
            if gap & mask != mask:
                ways.append(gaps.count(gap))
            else:
                return 0  # Only one solution exists for gap = 0 (mod n) without shared factors
    lengths = [0] * (n + 1)
    for gap in gaps:
        if gap != 0:
            if gap & mask != mask:
                for factor in factors:
                    if factor != 0 and factor != gap:
                        lengths[factor] += 1
                    else:
                        continue
                for i in range(n):
                    q = 0
                    for factor in factors:
                        q += lengths[factor] // (gap // factor + 1)
                    ways += q
                    lengths[factor] = q
    return pow(2, ways, MAX)

