from collections import defaultdict

def solve(n, edges):
    graph = defaultdict(list)
    in_degrees = defaultdict(int)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        in_degrees[v] += 1
        in_degrees[u] += 1

    # Process all junctions that had no connection to any other junction at the previous time
    # Once this cycle is found, there are cycle and the corresponding "ans" is zero
    while any(i == 0 for i in in_degrees.values()):
        ans = sum(min(i // 2, n - i) for i in in_degrees.values())
        for u in in_degrees.keys():
            if in_degrees[u] <= n // 2:
                for v in graph[u]:
                    in_degrees[v] -= 1
        graph = defaultdict(list)

    for u in range(1, n + 1):
        curr_level = [u]
        visited = set()
        skips = 0

        while curr_level:
            next_level = []
            if skips > 0:
                for j in curr_level:
                    for v in graph[j]:
                        if v not in visited:
                            next_level.append(v)
                skips -= 1
                continue
            for j in curr_level:
                for v in graph[j]:
                    if v not in visited:
                        next_level.append(v)
            curr_level = next_level
            visited |= set(curr_level)

        ans = min(ans, len(curr_level) * len(curr_level) - ans)

    return ans

