def count_cyclic_strings(n, s):
    if n == len(s):
        return 1  # The entire string itself is a valid cyclic string

    if n > len(s):
        return 0  # The given length is greater than the string length

    final_counts = {}
    def helper(i):
        if i in final_counts:
            return final_counts[i]
        if i == n:
            final_counts[i] = 1  # A valid cyclic string of length n
            return 1
        if i == n-1:
            count = 1
        else:
            prev_bit = s[i]
            remaining_length = n-i-1
            for next_bit in '01':
                if prev_bit == next_bit:
                    count += helper(i+1)
                else:
                    if i+remaining_length >= n:
                        count += helper(i+1)
                    for j in range(remaining_length):
                        bit = s[i+j + 1]  # Update the last bit
                        count += helper(i+1)
                        if remaining_length > 1:
                            s_char = s[i+j]  # Update a character
                            remaining_length -= 1
                            count += helper(i+1)
        final_counts[i] = count
        return count

    return helper(0)

