def ways_to_sort(n: int, m: int) -> int:
    MOD = 998244353
    dp = [1] * (m + 10)
    for i in range(m, 0, -1):
        for j in range(2, i + 1):
            dp[j] = (dp[j] + 2 * dp[j - 1]) % MOD
    ways = dp[m]
    dp[1] = 1
    for i in range(m - 1, 0, -1):
        dp[i] = (dp[i] + dp[i + 1]) % MOD
    return ways * dp[1] % MOD * (n - i + 1) % MOD

def solve(n: int, m: int) -> int:
    MOD = 998244353
    if m == 0:
        return 10**n
    nums = set(range(1, n + 1))
    ss = set()
    ss2 = set()
    for _ in range(m):
        x, y = map(int, input().split())
        if x == n:
            continue
        y -= 1 # Python ranges start from 1
        ss.add((x, y))
    for i in range(1, n):
        for j in [k for k in range(1, i) if k not in ss]:
            insort_left(nums, j)
    # number of all increasing queries: n*(n) = n*(n-1)//2 (this time we do not add cycle ending in min(x[i], y[i]))
    ret = 1
    for x, y in ss:
        ret = (ret * ways_to_sort(y - 1, n - x) * (n - x)) % MOD
    return ret

