import heapq

def find_unpaired_cost(cost_matrix):
    n = len(cost_matrix)
    distances = [[float('inf')] * n for _ in range(n)]
    pairs = [-1] * n

    for i in range(n):
        for j in range(i, n):
            if i != j:
                distances[i][j] = min(cost_matrix[i][j], cost_matrix[j][i])
                pairs[j] = i if cost_matrix[i][j] < cost_matrix[j][i] else j

    min_q = [(distances[0][1], 0, 1)]
    min_dist = None
    while min_q and min_q[0][0] <= min_dist:
        _, i, j = heapq.heappop(min_q)
        if i != 1 and j != 0 and distances[i][j] + distances[0][1] < distances[i][0]:
            distances[i][0] = distances[i][1] + min_dist
        else:
            distances[i][0] = min(distances[i], distances[j], distances[1])
        if (i, j) == (0, 1) and distances[0][1] + min_dist < distances[1][0]:
            distances[1][0] = distances[0][1] + min_dist

        for k in range(n):
            if k != i and k != j:
                heapq.heappush(min_q, (distances[i][k] + distances[k][j] + distances[i][0], i, k))

    return min(q[0] - distances[i][1] for i, q in enumerate(zip([min(d) for d in distances])))

