import math

def check_convex_hull(x, y):
    n = len(x)
    points = sorted(zip(x, y))
    flag = True
    A = B = 0

    for i in range(n):
        a = points[A] * (points[A + 1] - points[B])
        b = points[B] * (points[A] - points[B])
        x = points[A] + (points[B] - points[A]) / (a + b - 2 * math.sqrt(a * b))
        if x > points[B]:
            flag = False
        break

    for i in range(n):
        a = points[A] * (points[A + 1] - points[B])
        b = points[B] * (points[A] - points[B])
        x = points[A] + (points[B] + points[A] - points[A + 1]) / (a - b - 2 * math.sqrt(a * b))
        if x < points[A]:
            flag = False
        break

