from typing import List

def find_set(u: int, parent: List[int]) -> int:
    while u != parent[u]:
        u = parent[u]
    return u

def union_sets(u: int, v: int, parent: List[int], rank: List[int]):
    pu = find_set(u, parent)
    pv = find_set(v, parent)
    if pu == pv:
        return
    if rank[pu] < rank[pv]:
        parent[pu] = pv
    elif rank[pu] > rank[pv]:
        parent[pv] = pu
    else:
        parent[pv] = pu
        rank[pu] += 1

def maximum_mst(weight: List[int]) -> int:
    n = len(weight)
    parent = list(range(n))
    rank = [0] * n
    while True:
        sets: List[set[int]] = []
        for i in range(n):
            if find_set(i, parent) not in sets:
                sets.append(set([i]))
            for j in range(i + 1, n):
                if find_set(i, parent) != find_set(j, parent) and weight[i] < weight[j]:
                    union_sets(i, j, parent, rank)
                    sets.append(sets[i].union(sets[j]))
                elif weight[i] > weight[j]:
                    union_sets(i, j, parent, rank)
        if len(sets) == 1:
            break
    return max(weight[i] for i in range(n))

