    while True:
        new_stages = city_to_stage.copy()
        for i, stages_cnt in city_to_stage.items():
            for j, stage_cnts in city_to_stage.items():
                if stages[i - 1][j - 1] < stages_cnt[stage_cnts[0]][stage_cnts[1]]:  # Change link
                    new_stages[i] = new_stages[i] + (j,)
                    break
        else:
            if city_to_stage == new_stages:
                break  # Pairing is stable
            for i, stages_cnts in city_to_stage.items():
                for j, stage_cnts in city_to_stage.items():
                    if not stages[i - 1][j - 1] < stages_cnts[stage_cnts[0]][stage_cnts[1]]:
                        city_to_stage = {i: (i, j) for i, j in stages_cnts}
                        break
                else:
                    continue
                break
            else:
                return "-1"
        city_to_stage = new_stages
    return ' -> '.join(map(str, city_to_stage[k] for k in range(1, N + 1)))

