from collections import defaultdict

class ArraySimilaritySolver:
    def __init__(self, a, b, queries):
        self.a = a
        self.b = b
        self.que = queries
        self.dp = [[-1] * 2**14 for _ in range(len(queries))]

    def transform(self, arr, nums, k, x):
        current = arr[:k]
        flag = True
        for i in range(len(current)):
            current[i] = current[i] ^ x
            if current[i] != nums[i % k]:
                flag = False
                break
        if flag:
            return 0
        else:
            return -1

    def sim(self, a, b, k, x):
        return self.transform(a, b, k, x)

    def process_sim(self, i):
        if self.dp[i][self.a[-1]] != -1:
            return self.dp[i][self.a[-1]]
        result = self.sim(self.a, self.b, k, self.a(self.a))
        self.dp[i][self.a[-1]] = result
        return result

    def simulate(self, q):
        result = [0] * q
        for i in range(q):
            if i == 0:
                result[i] = self.process_sim(i)
                continue
            dp = [-1] * 2**14
            old_sim = result[i-1]
            result[i] = old_sim
            for idx in range(len(self.a)):
                if self.a[idx] + (1 << i) - old_sim in dp:
                    continue
                for x in range(1, 15):
                    for off in range(1 << x):
                        new_idx = idx + off
                        if self.a[idx] + off == -1:
                            continue
                        diff = self.a[new_idx] ^ self.a[idx]
                        if diff & (1 << x - 1):
                            continue
                        zero_diff = diff & (old_sim ^ self.b[idx % k])
                        mask_1 = (0x00FFFFFF & ~ self.a[new_idx % k] ^ self.a[idx % k])
                        mask_2 = (x - 1) << (14 - x)
                        sim_0_1 = self.a[idx] + (1 << i)
                        shift_0_1 = 1 << i
                        sim_1_1 = diff & (1 << (x - 1)) ^ self.b[new_idx % k]
                        if (self.a[new_idx + shift_0_1 >> x - 1] == old_sim % (1 << x)):
                            continue
                        sim_1_1 += shift_0_1
                        min_sim = self.process_sim(i - 1)
                        if sim_1_1 != -1 and min_sim > sim_1_1:
                            dp[self.a.index(sim_1_1)] = difflinac(0)
        return result

    def solve(self):
        self.dp[0] = [0] * 2**14
        self.dp[0][self.b[0]] = 1
        for i in range(len(self.que) - 1):
            self.dp[i + 1] = self.dp[i]
        self.sim(self.a, self.b, k, self.a[0])
        return self.similarity[self.que[-1]]

def test_1():
    q = 1
    el = [["a", 2, 5]]
    a = [[0, 4, 2]]
    b = [[1, 2, 3]]
    arb = ArraySimilaritySolver(a, b, q)
    res = arb.solve()
    assert res == -1

