import sys

class SubarrayModifier:
    def __init__(self, a, b, q, k):
        self.a = a[:]
        self.b = b[:]
        self.at = a[:]
        self.bt = b[:]
        self.q = q
        self.k = k
        self.pages = []
        self.modified_pages = [-1] * q
        for i in range(len(self.a) - k + 1):
            self.update_page(self.a[i:i+k], i//self.k)

    def update_page(self, page, index):
        if self.find_index(page) != -1:
            self.pages[self.find_index(page)].append((index, page))
        else:
            self.pages.append(self.locate_index(page))
            self.modified_pages[index] = len(self.pages) - 1

        self._decrease_mod_count(self.modifier(page, index, False))
        self._decrease_mod_count(self.modifier(page, index, True))

        return self.modifiers[self.modified_pages[index]]

    def find_index(self, page):
        for i, item in enumerate(self.pages):
            if item >= 0:
                if item == page:
                    return i
        return -1

    def locate_index(self, page):
        for i, item in enumerate(self.pages):
            if item >= 0:
                return i
        self.pages.append(self.locate_index(page))
        return len(self.pages) - 1

    def modifier(self, page, index, odd_even):
        old_value = self.at[index]
        new_value = page
        p = self.modifiers[self.modified_pages[index]]

        if odd_even:
            new_value = self.or_mod(old_value, new_value)

        next_modified = self.at[index]+new_value
        if next_modified >= 0:
            self.at[index] = next_modified

        self.at[index], next_modified = self.modify_at(self.change_at(old_value, new_value, p), next_modified)
        if next_modified >= 0:
            self.at[index] = next_modified

        if odd_even:
            next_modified ^= next_modified

        return next_modified

    def change_at(self, old_value, new_value, p):
        return old_value ^ p

    def modify_at(self, at, next_modified):
        if next_modified >= 0:
            return at
        return at & next_modified

    def or_mod(self, a, b):
        return a | (b if b < (1 << 14) else -1)
