import sys

def encode_permutation(code):
    n = len(code)
    marked = [False] * n
    encoded_permutation = [0] * n

    for i in range(n):
        found = False

        for j in range(n):
            if not marked[j] and code[i] == j:
                encoded_permutation[i] = j + 1
                found = True
                break

        if not found:
            encoded_permutation[i] = -1

    return encoded_permutation

def find_permutation(perm_code, n):
    max_perm = [0] * n
    max_perm[0] = 1

    for i in range(1, n):
        indexes = [0]
        value = perm_code[i] - 1

        while index := max_perm[value]:
            indexes.append(index)
            value = perm_code[index] - 1

        max_perm[value] = i + 1

        for adj in indexes:
            for jp in range(max(0, adj + 1), max(0, adj - n + 1) + 1):
                if perm_code[jp - 1] > perm_code[adj - 1]:
                    break
            else:
                break

    return max_perm

def decode_permutation(perm_code, n):
    encoded_perm = [0] * n
    perm = [-1] * n

    for i in range(n):
        if perm_code[i] == -1:
            perm[perm_code[i] - 1] = n - i
        else:
            encoded_perm[perm_code[i] - 1] = n - i

    for i in range(n):
        if perm_code[i] != -1:
            perm[perm_code[i] - 1] = i + 1

    for i in range(n):
        perm[i] *= -1
    perm_code[:] = perm_code
    return perm_code

def main(n, perm_code):
    # Ensure the list doesn't get modified in-place
    perm_code = perm_code[:]

    min_index_permutation = encode_permutation(perm_code[:])
    encoded_permutation = find_permutation(min_index_permutation, n)

    decoded_permutation = decode_permutation(encoded_permutation, n)

    return decoded_permutation

if __name__ == "__main__":
    n = int(sys.stdin.readline().strip())
    perm_code = [int(num) for num in sys.stdin.readline().strip().split()]
    perm = main(n, perm_code)
    for num in perm:
        print(num, end=' ')
    print()
