mod = 10**9 + 7

def ncr(n, r):
    if n < r: 
        return 0

    num = factorial(n)
    den = factorial(r) * factorial(n-r)
    return num * power(den, mod-2, mod) % mod

def power(x, y, p):
    res = 1
    x = x % p
    while y > 0:
        if y & 1:
            res = (res * x) % p
        y = y >> 1
        x = (x*x) % p
    return res

def solve(n, p):
    if n == 1:
        return 1
    if p[n-1] == 1:
        return n * solve(n-1, p) % mod

