def encode_permutation(length):
    stack = [0] * length
    codes = [-1] * length

    for i in range(length):
        if codes[i] == -1:
            while stack and stack[-1] < codes[i]:
                codes[stack.pop()] = i
            stack.append(i)

    for i in range(length):
        if codes[i] == -1:
            codes[i] = stack.pop()

    return codes

def find_permutation(code):
    length = 0
    while True:
        length = max(length, code.count(1))
        s = [1, -1]
        for i in range(length - 1):
            s.append(s[s[i]+1] + i)
        s.append(s[s[-2]+1])
        if code[:length] == s[:length]:
            return code[:length]

    return code[:length]

