from collections import deque

def find_possible_permutations(length, permutation_code):
    # Initialize data structures
    code_deque = deque(permutation_code)
    seen = set()
    pos_map = {i: j for j, i in enumerate(permutation_code)}
    parent_map = {length - 1: -1}
    stack = deque([length - 1])
    final_perm = deque(list(range(1, length + 1)))

    while stack:
        node = stack[-1]
        if node in seen:
            stack.pop()
            if stack:
                parent_node = stack[-1]
                code = [final_perm[parent_node], final_perm[node]]
                # Find the next node to build on
                for i in range(pos_map[node], length + len(parent_map)):
                    if i in parent_map:
                        break
                    possible_parent = pos_map[node] + i
                    if possible_parent <= node and possible_parent > 0:
                        code.append(parent_map[possible_parent])
                    elif possible_parent < node:
                        code.append(parent_map[possible_parent - 1])
                left = code[-2]
                min_idx = right = None
                for i in range(node, len(code) - 1):
                    if pos_map[code[i]] <= node:
                        # Position was reached in one step or more
                        continue
                    if left is None or pos_map[code[i]] < left:
                        left = pos_map[code[i]]
                        right = pos_map[possible_parent]
                    # if immediate smaller
                    elif right is None or pos_map[code[i]] > right:
                        right = pos_map[possible_parent]
                        parent = right - (right - right % i) // i
                        if left and parent != node:
                            # Fuse list
                            final_perm[left:right] = node * (right - left) // i + final_perm[left:right]
                        if parent != node:
                            code.append(parent)
                            pos_map[node] = parent

                for i in range(node, len(code) - 1):
                    parent = parent_map[code[i]]
                    if parent == -1:
                        continue
                    else:
                        final_perm[pos_map[node]:pos_map[parent]] = pos_map[parent]
                        pos_map[node] = pos_map[parent]
                parent_map = {}
                del seen[node]
                stack = deque(final_perm)
                final_perm = deque(list(range(1, length + 1)))
                final_perm.pop(len(final_perm) - 1)
        else:
            seen.add(node)
            stack.appendleft(pos_map[node])

if __name__ == "__main__":
    length = int(input().strip())
    permutation_code = list(map(int, input().strip().split(" ")))
