from collections import deque

def maximal_pairs(n, streets):
    # Use BFS to find the maximum number of pairs
    max_pairs = 0
    visited = [False] * (n + 1)

    for start in range(1, n + 1):
        if not visited[start]:
            queue = deque([(start, 0)])
            max_capacity = 0

            while queue:
                node, capacity = queue.popleft()

                for neighbor in range(1, n + 1):
                    if visited[neighbor]:
                        continue

                    # Calculate adjacency
                    adj_node, adj_capacity = streets[node - 1][neighbor - 1]
                    if adj_capacity > capacity + 1:
                        max_capacity = (max_capacity, capacity + 1)[adj_capacity == capacity + 1]

                    if neighbor != node and capacity:
                        queue.append((neighbor, capacity))

                    if capacity == 1 and not visited[neighbor]:
                        visited[neighbor] = True

            max_pairs += len(streets) + max_capacity

    return max_pairs

