from collections import defaultdict

def directed_path_count(n, m, edges):
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    # Build graph from edges
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    zero_in_degree = [node for node, degree in enumerate(in_degree) if degree == 0]

    directed_path_count = 0

    for i in range(1, n + 1):
        if i in zero_in_degree:
            for child in graph[i]:
                in_degree[child] -= 1
                if in_degree[child] == 0:
                    zero_in_degree.append(child)

    for node in zero_in_degree:
        directed_path_count += (n - in_degree[node])

    return directed_path_count

