from functools import lru_cache

def count_triangles(n, m, visibility=True):
    @lru_cache(maxsize=None)
    def dfs(i, cumulative_triangles, visible, drawn):
        if i == n:
            return cumulative_triangles
        total_triangles = cumulative_triangles
        for j in range(visible + 1):
            if j in drawn:
                continue
            for k in range(i):
                holes = n + 1 - 2 - j
                if not visibility or k < holes:
                    total_triangles += dfs(k + 1, cumulative_triangles + 1, visible & (j + 1 == visible + 1), j.union(drawn))
        return total_triangles
    return dfs(0, 0, m * (m - 1) // 2 + m, set())

if __name__ == "__main__":
